    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            results.append(f"{path}.{k}: type={type(v).__name__}")
            if isinstance(v, (list, dict)):
                results.extend(find_nested_shapes(v, f"{path}.{k}"))
    elif isinstance(obj, list):
        print(f"path={path}: list of {len(obj)} elements")
        for i, v in enumerate(obj):
            if isinstance(v, list):
                results.append(f"{path}[{i}]: inner list of {len(v)}")
            elif isinstance(v, dict):
                print(f"  [{i}] dict with keys: {list(v.keys())}")
    return results

